def solve(data):
    a = data['a']
    b = data['b']

    # If both strings are empty, no operations needed
    if not a and not b:
        return 0

    # Initialize DP table with dimensions (len(a)+1) x (len(b)+1)
    dp = [[0] * (len(b)+1) for _ in range(len(a)+1)]

    # Fill the DP table
    for i in range(1, len(a)+1):
        for j in range(1, len(b)+1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1

    # The result is the value in the bottom-right corner of the DP table
    return dp[-1][-1]

